// Merge incoming message with loaded session
const body = $('Webhook Entry').first().json.body;
const sessionRows = $input.all();

let session = {};
if (sessionRows.length > 0 && sessionRows[0].json && sessionRows[0].json.session_id) {
  session = sessionRows[0].json;
} else {
  session = {
    session_id: body.session_id,
    phase: 1,
    product_name: null,
    product_list: [],
    history: []
  };
}

// Normalise types
session.phase = parseInt(session.phase) || 1;
session.product_list = Array.isArray(session.product_list) ? session.product_list
  : (typeof session.product_list === 'string' ? JSON.parse(session.product_list || '[]') : []);
session.history = Array.isArray(session.history) ? session.history
  : (typeof session.history === 'string' ? JSON.parse(session.history || '[]') : []);

return [{
  json: {
    message: body.message,
    session_id: body.session_id,
    session
  }
}];

