// Parse Claude's intent response safely
const raw = $input.first().json.text || $input.first().json.content || '';
const message = $('Merge Session State').first().json.message;
const session = $('Merge Session State').first().json.session;
const session_id = $('Merge Session State').first().json.session_id;

let intent = {};
try {
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  intent = JSON.parse(cleaned);
} catch (e) {
  intent = {
    intent_type: 'other',
    product_name: null,
    query_string: null,
    budget_inr: null,
    response_to_user: 'I had a moment of confusion. Could you tell me what product you are looking for?'
  };
}

// Ensure intent_type is valid
const valid = ['vague_query','direct_product','approval','rejection','selection','other'];
if (!valid.includes(intent.intent_type)) {
  intent.intent_type = 'other';
}

return [{
  json: {
    intent,
    message,
    session_id,
    session
  }
}];

// Merge primary and fallback selectors, deduplicate, cap at 8
const data = $input.first().json;
const primary = Array.isArray(data.products_primary) ? data.products_primary : [];
const fallback = Array.isArray(data.products_fallback) ? data.products_fallback : [];

const combined = [...new Set([...primary, ...fallback])]
  .map(p => p.trim())
  .filter(p => p.length > 3)
  .slice(0, 8);

const session = $('Parse Intent JSON').first().json.session;
const session_id = $('Parse Intent JSON').first().json.session_id;
const intent = $('Parse Intent JSON').first().json.intent;

if (combined.length === 0) {
  return [{
    json: {
      error: 'empty_results',
      reply: "I couldn't find results for that. Try a slightly different product name?",
      session_id,
      session
    }
  }];
}

return [{
  json: {
    product_list: combined,
    session_id,
    session,
    intent
  }
}];

