const raw = $input.first().json.text || $input.first().json.content || '';
const session_id = $('Parse Intent JSON').first().json.session_id;
const session = $('Parse Intent JSON').first().json.session;

let selected_product = null;
try {
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  const parsed = JSON.parse(cleaned);
  selected_product = parsed.selected_product;
} catch(e) {
  selected_product = session.product_list[0] || null;
}

return [{
  json: { selected_product, session_id, session }
}];

const reply = $input.first().json.text || $input.first().json.content || '';
const ctx = $('B1b — Parse Selection').first().json;
const session = { ...ctx.session };

session.phase = 2;
session.product_name = ctx.selected_product;
session.history = Array.isArray(session.history) ? session.history : [];
session.history.push({ role: 'user', content: `Selected: ${ctx.selected_product}` });
session.history.push({ role: 'assistant', content: reply });

return [{
  json: { session_id: ctx.session_id, session, reply }
}];

const reply = $input.first().json.text || $input.first().json.content || '';
const ctx = $('Parse Intent JSON').first().json;
const session = { ...ctx.session };

session.phase = 2;
session.product_name = ctx.intent.product_name;
session.history = Array.isArray(session.history) ? session.history : [];
session.history.push({ role: 'user', content: ctx.message });
session.history.push({ role: 'assistant', content: reply });

return [{
  json: { session_id: ctx.session_id, session, reply }
}];

// D1 Guard: only proceed if phase=2 and product_name is set
const ctx = $('Parse Intent JSON').first().json;
const session = ctx.session;

if (session.phase !== 2 || !session.product_name) {
  return [{
    json: {
      guard_failed: true,
      reply: "Hmm, I'm not sure which product you want me to compare. Could you tell me the product name or pick one from the list?",
      session_id: ctx.session_id,
      session
    }
  }];
}

return [{
  json: {
    guard_failed: false,
    product_name: session.product_name,
    session_id: ctx.session_id,
    session
  }
}];

// Zip the arrays into listing objects
const data = $input.first().json;
const product_titles = Array.isArray(data.product_titles) ? data.product_titles : [];
const store_names = Array.isArray(data.store_names) ? data.store_names : [];
const prices = Array.isArray(data.prices) ? data.prices : [];
const mrps = Array.isArray(data.mrps) ? data.mrps : [];
const availabilities = Array.isArray(data.availabilities) ? data.availabilities : [];
const links = Array.isArray(data.links) ? data.links : [];

const len = Math.max(store_names.length, prices.length, product_titles.length);

if (len === 0) {
  return [{
    json: {
      error: 'empty_results',
      reply: "I couldn't find comparison data for that product right now. Try a slightly different product name?",
      session_id: $('D1 — Guard Check').first().json.session_id,
      session: $('D1 — Guard Check').first().json.session
    }
  }];
}

const listings = [];
for (let i = 0; i < len; i++) {
  listings.push({
    product_name: product_titles[i] || null,
    store: store_names[i] || null,
    price: prices[i] || null,
    mrp: mrps[i] || null,
    availability: availabilities[i] || null,
    link: links[i] ? `https://buyhatke.com${links[i].startsWith('/') ? links[i] : '/' + links[i]}` : null
  });
}

return [{
  json: {
    listings,
    product_name: $('D1 — Guard Check').first().json.product_name,
    session_id: $('D1 — Guard Check').first().json.session_id,
    session: $('D1 — Guard Check').first().json.session
  }
}];

const reply = $input.first().json.text || $input.first().json.content || '';
